-- FINAGRO Web — managerial chart mappings foundation.
-- Spreadsheet-derived mappings are ID-based; report calculation is intentionally out of scope.

create table public.reporting_templates (
 id uuid primary key, code text not null, version text not null, name text not null,
 date_basis text not null check(date_basis in ('ISSUE_DATE','DUE_DATE','SPECIAL')),
 is_active boolean not null default true, created_at timestamptz not null default now(),
 unique(code,version), unique(id,code)
);
create table public.report_line_templates (
 id uuid primary key, reporting_template_id uuid not null references public.reporting_templates(id) on delete cascade,
 parent_id uuid, code text not null, label text not null,
 line_type text not null check(line_type in ('ACCOUNT','CALCULATED','SECTION')),
 display_order integer not null, calculation jsonb,
 confidence text not null check(confidence in ('confirmed_spreadsheet','confirmed_tutorial','confirmed_both','inferred_needs_validation')),
 check((line_type='CALCULATED' and calculation is not null) or (line_type<>'CALCULATED' and calculation is null)),
 unique(reporting_template_id,code), unique(id,reporting_template_id),
 foreign key(parent_id,reporting_template_id) references public.report_line_templates(id,reporting_template_id)
);
create table public.report_account_template_mappings (
 id uuid primary key, reporting_template_id uuid not null,
 report_line_template_id uuid not null, chart_template_id uuid not null,
 chart_template_item_id uuid not null, managerial_role text not null,
 typical_direction text check(typical_direction in ('ENTRADA','SAIDA','NEUTRA')),
 recognition_basis text not null check(recognition_basis in ('ISSUE_DATE','DUE_DATE','SPECIAL')),
 crop_filter_mode text not null default 'NONE',
 confidence text not null check(confidence in ('confirmed_spreadsheet','confirmed_tutorial','confirmed_both')),
 evidence text not null,
 unique(reporting_template_id,chart_template_item_id,report_line_template_id),
 foreign key(report_line_template_id,reporting_template_id) references public.report_line_templates(id,reporting_template_id),
 foreign key(chart_template_item_id,chart_template_id) references public.chart_account_template_items(id,template_id)
);
create table public.reporting_structures (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id),
 reporting_template_id uuid references public.reporting_templates(id), code text not null, version text not null,
 name text not null, date_basis text not null check(date_basis in ('ISSUE_DATE','DUE_DATE','SPECIAL')),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(organization_id,code), unique(id,organization_id), unique(organization_id,reporting_template_id)
);
create table public.report_lines (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null, reporting_structure_id uuid not null,
 source_template_line_id uuid references public.report_line_templates(id), parent_id uuid,
 code text not null, label text not null,
 line_type text not null check(line_type in ('ACCOUNT','CALCULATED','SECTION')),
 display_order integer not null, calculation jsonb,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check((line_type='CALCULATED' and calculation is not null) or (line_type<>'CALCULATED' and calculation is null)),
 unique(organization_id,reporting_structure_id,code), unique(id,organization_id),
 foreign key(reporting_structure_id,organization_id) references public.reporting_structures(id,organization_id) on delete cascade,
 foreign key(parent_id,organization_id) references public.report_lines(id,organization_id)
);
create table public.report_account_mappings (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null,
 reporting_structure_id uuid not null, report_line_id uuid not null, chart_account_id uuid not null,
 managerial_role text not null, typical_direction text check(typical_direction in ('ENTRADA','SAIDA','NEUTRA')),
 recognition_basis text not null check(recognition_basis in ('ISSUE_DATE','DUE_DATE','SPECIAL')),
 crop_filter_mode text not null default 'NONE', evidence text,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(organization_id,reporting_structure_id,chart_account_id,report_line_id), unique(id,organization_id),
 foreign key(reporting_structure_id,organization_id) references public.reporting_structures(id,organization_id) on delete cascade,
 foreign key(report_line_id,organization_id) references public.report_lines(id,organization_id) on delete cascade,
 foreign key(chart_account_id,organization_id) references public.chart_accounts(id,organization_id)
);

create or replace function private.guard_report_line_hierarchy() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.parent_id=new.id then raise exception 'REPORT_LINE_CANNOT_PARENT_ITSELF'; end if;
 if new.parent_id is not null and not exists(select 1 from public.report_lines p where p.id=new.parent_id and p.organization_id=new.organization_id and p.reporting_structure_id=new.reporting_structure_id) then raise exception 'REPORT_LINE_PARENT_NOT_FOUND'; end if;
 if new.parent_id is not null and exists(with recursive a as (select p.parent_id from public.report_lines p where p.id=new.parent_id union all select p.parent_id from public.report_lines p join a on p.id=a.parent_id) select 1 from a where parent_id=new.id) then raise exception 'REPORT_LINE_HIERARCHY_CYCLE'; end if;
 return new;
end$$;
create trigger trg_report_lines_hierarchy before insert or update of parent_id,organization_id,reporting_structure_id on public.report_lines for each row execute function private.guard_report_line_hierarchy();

create or replace function private.guard_report_mapping() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.report_lines l where l.id=new.report_line_id and l.organization_id=new.organization_id and l.reporting_structure_id=new.reporting_structure_id and l.line_type='ACCOUNT') then raise exception 'REPORT_MAPPING_REQUIRES_ACCOUNT_LINE'; end if;
 return new;
end$$;
create trigger trg_report_account_mappings_guard before insert or update on public.report_account_mappings for each row execute function private.guard_report_mapping();

alter table public.reporting_templates enable row level security;
alter table public.report_line_templates enable row level security;
alter table public.report_account_template_mappings enable row level security;
alter table public.reporting_structures enable row level security;
alter table public.report_lines enable row level security;
alter table public.report_account_mappings enable row level security;
create policy reporting_templates_read on public.reporting_templates for select to authenticated using(true);
create policy report_line_templates_read on public.report_line_templates for select to authenticated using(true);
create policy report_account_template_mappings_read on public.report_account_template_mappings for select to authenticated using(true);
create policy reporting_structures_read on public.reporting_structures for select to authenticated using(private.has_permission(organization_id,'reports.view'));
create policy reporting_structures_write on public.reporting_structures for all to authenticated using(private.has_permission(organization_id,'chart_accounts.manage')) with check(private.has_permission(organization_id,'chart_accounts.manage'));
create policy report_lines_read on public.report_lines for select to authenticated using(private.has_permission(organization_id,'reports.view'));
create policy report_lines_write on public.report_lines for all to authenticated using(private.has_permission(organization_id,'chart_accounts.manage')) with check(private.has_permission(organization_id,'chart_accounts.manage'));
create policy report_account_mappings_read on public.report_account_mappings for select to authenticated using(private.has_permission(organization_id,'reports.view'));
create policy report_account_mappings_write on public.report_account_mappings for all to authenticated using(private.has_permission(organization_id,'chart_accounts.manage')) with check(private.has_permission(organization_id,'chart_accounts.manage'));

create trigger trg_reporting_structures_updated_at before update on public.reporting_structures for each row execute function private.set_updated_at();
create trigger trg_report_lines_updated_at before update on public.report_lines for each row execute function private.set_updated_at();
create trigger trg_report_account_mappings_updated_at before update on public.report_account_mappings for each row execute function private.set_updated_at();
create trigger trg_reporting_structures_audit after insert or update or delete on public.reporting_structures for each row execute function private.audit_row_change();
create trigger trg_report_lines_audit after insert or update or delete on public.report_lines for each row execute function private.audit_row_change();
create trigger trg_report_account_mappings_audit after insert or update or delete on public.report_account_mappings for each row execute function private.audit_row_change();


