insert into public.report_account_template_mappings(id,reporting_template_id,report_line_template_id,chart_template_id,chart_template_item_id,managerial_role,typical_direction,recognition_basis,crop_filter_mode,confidence,evidence)
select (v->>'id')::uuid,(select id from public.reporting_templates where code=v->>'structure' and version='1.0.0'),
       (select id from public.report_line_templates where code=v->>'line_code' and reporting_template_id=(select id from public.reporting_templates where code=v->>'structure' and version='1.0.0')),
       '3269e51b-12de-5887-a85c-4461af91b4e9'::uuid,(v->>'item_id')::uuid,v->>'managerial_role',v->>'typical_direction',v->>'recognition_basis',v->>'crop_filter_mode',v->>'confidence',v->>'evidence'
from d;


create or replace function public.apply_reporting_template(p_organization_id uuid,p_reporting_template_id uuid)
returns boolean language plpgsql security definer set search_path='' as $$
declare t public.reporting_templates%rowtype; s_id uuid; line record; line_map jsonb='{}'::jsonb; new_line uuid;
begin
 if auth.uid() is null or not private.has_permission(p_organization_id,'chart_accounts.manage') then raise exception 'PERMISSION_DENIED'; end if;
 select * into t from public.reporting_templates where id=p_reporting_template_id and is_active;
 if not found then raise exception 'REPORTING_TEMPLATE_NOT_FOUND'; end if;
 if exists(select 1 from public.reporting_structures where organization_id=p_organization_id and reporting_template_id=t.id) then return false; end if;
 if exists(select 1 from public.report_account_template_mappings m where m.reporting_template_id=t.id and not exists(select 1 from public.chart_accounts a where a.organization_id=p_organization_id and a.source_template_item_id=m.chart_template_item_id)) then raise exception 'ORGANIZATION_CHART_TEMPLATE_REQUIRED'; end if;
 insert into public.reporting_structures(organization_id,reporting_template_id,code,version,name,date_basis) values(p_organization_id,t.id,t.code,t.version,t.name,t.date_basis) returning id into s_id;
 for line in with recursive tree as (select l.*,1 depth from public.report_line_templates l where l.reporting_template_id=t.id and l.parent_id is null union all select l.*,tree.depth+1 from public.report_line_templates l join tree on l.parent_id=tree.id) select * from tree order by depth,display_order,code loop
   new_line=gen_random_uuid();
   insert into public.report_lines(id,organization_id,reporting_structure_id,source_template_line_id,parent_id,code,label,line_type,display_order,calculation) values(new_line,p_organization_id,s_id,line.id,case when line.parent_id is null then null else (line_map->>line.parent_id::text)::uuid end,line.code,line.label,line.line_type,line.display_order,line.calculation);
   line_map=line_map||jsonb_build_object(line.id::text,new_line::text);
 end loop;
 insert into public.report_account_mappings(organization_id,reporting_structure_id,report_line_id,chart_account_id,managerial_role,typical_direction,recognition_basis,crop_filter_mode,evidence)
 select p_organization_id,s_id,(line_map->>m.report_line_template_id::text)::uuid,a.id,m.managerial_role,m.typical_direction,m.recognition_basis,m.crop_filter_mode,m.evidence
 from public.report_account_template_mappings m join public.chart_accounts a on a.organization_id=p_organization_id and a.source_template_item_id=m.chart_template_item_id where m.reporting_template_id=t.id;
 return true;
end$$;
revoke all on function public.apply_reporting_template(uuid,uuid) from public;
grant execute on function public.apply_reporting_template(uuid,uuid) to authenticated;
grant select on public.reporting_templates,public.report_line_templates,public.report_account_template_mappings,public.reporting_structures,public.report_lines,public.report_account_mappings to authenticated;
grant insert,update,delete on public.reporting_structures,public.report_lines,public.report_account_mappings to authenticated;
